'use strict';

var words2uint64 = require( '@stdlib/number/uint64/ctor' ).of;
var lpad = require( '@stdlib/string/base/left-pad' );
var or = require( './../lib' );

// Define a mask that sets the middle 32 bits (bits 16 to 47):
var mask = words2uint64( 0x0000ffff, 0xffff0000 );

// Define a function for converting to 64-bit fixed length hex string:
function toHex64( x ) {
	return '0x'+lpad( x.toString( 16 ), 16, '0' );
}

var values = [
	words2uint64( 0x12340000, 0x0000def0 ),
	words2uint64( 0x11112222, 0x33334444 ),
	words2uint64( 0xaaaabbbb, 0xccccdddd ),
	words2uint64( 0x00000000, 0x00000000 )
];

var v;
var i;
for ( i = 0; i < values.length; i++ ) {
	v = or( values[ i ], mask );
	console.log( '%s | %s = %s', toHex64( values[ i ] ), toHex64( mask ), toHex64( v ) );
}
